#include <algorithm>
#include <iostream>
#include <vector>
std::vector<int> shifted_copy(const std::vector<int>& source, int delta) {
    std::vector<int> result;
    // TODO: crea le celle, copia con std::copy e modifica solo la copia.
    result.resize(source.size());
    std::copy(source.begin(), source.end(), result.begin());
    for (int& x : result) x += delta;
    return result;
}
int main() {
    int n=0,delta=0;std::cin >> n >> delta;
    std::vector<int> source(n);
    for(int& x:source) std::cin >> x;
    auto result=shifted_copy(source,delta);
    std::cout << result.size() << ' ';
    for(int x:result) std::cout << x << ' ';
    std::cout << source.size() << ' ';
    for(int x:source) std::cout << x << ' ';
}

