#include <iostream>
#include <map>
#include <string>
int lookup(const std::map<std::string,int>& values,
           const std::string& key, int fallback) {
    // TODO: restituisci il valore esistente o fallback, senza inserire.
    auto it = values.find(key);
    if (it == values.end()) return fallback;
    return it->second;
}
int main() {
    int n=0,fallback=0;std::cin >> n >> fallback;
    std::map<std::string,int> values;
    for(int i=0;i<n;++i) {
        std::string key;int value=0;std::cin >> key >> value;
        values.insert_or_assign(key,value);
    }
    std::string query;std::cin >> query;
    const auto before=values.size();
    std::cout << lookup(values,query,fallback) << ' '
              << before << ' ' << values.size();
}

