#include <iostream>
std::function<int(int)> make_offset(int offset) {
    // TODO: restituisci una lambda con uno snapshot proprio di offset.
    return [offset](int x) { return x + offset; };
}
int main() {
    int offset=0,x=0,new_offset=0;
    std::cin >> offset >> x >> new_offset;
    auto first=make_offset(offset);
    auto copied=first;
    offset=new_offset;
    std::cout << first(x) << ' ' << copied(x) << ' ' << offset;
}

